"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { ArrowLeft, ArrowRight, Check, Eye, Pause, X } from "lucide-react";
import { tutorialCatalog, type TutorialName } from "@/lib/vendor/tutorial-catalog";
import { readTutorialProgress, saveTutorialProgress } from "@/lib/vendor/tutorial-progress";
import TutorialLibrary from "./TutorialLibrary";
import s from "./guided-coach.module.css";
const visible=(selector?:string)=>selector?Array.from(document.querySelectorAll<HTMLElement>(selector)).find(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.height>0;}):undefined;
export default function VendorGuidedTours(){
 const router=useRouter();const pathname=usePathname();const params=useSearchParams();const route=pathname+(params.size?`?${params.toString()}`:"");
 const [library,setLibrary]=useState(false);const [welcome,setWelcome]=useState(false);const [tour,setTour]=useState<TutorialName|null>(null);const [index,setIndex]=useState(0);const [root,setRoot]=useState<HTMLElement|null>(null);const [spot,setSpot]=useState<{left:number;top:number;width:number;height:number}|null>(null);const [found,setFound]=useState(false);const [minimized,setMinimized]=useState(false);const [ready,setReady]=useState(false);
 const trigger=useRef<HTMLElement|null>(null);const heading=useRef<HTMLHeadingElement>(null);const definition=tour?tutorialCatalog[tour]:null;const step=definition?.steps[index];
 const close=useCallback((complete=false)=>{if(tour)saveTutorialProgress(tour,index,complete);setTour(null);setSpot(null);setMinimized(false);dispatchEvent(new CustomEvent("vendor-tour:close-more"));trigger.current?.focus();},[tour,index]);
 function start(name:TutorialName,resume=false){if(!tutorialCatalog[name])return;trigger.current=document.activeElement as HTMLElement;const saved=readTutorialProgress()[name];const next=resume&&!saved?.complete?saved?.step??0:0;dispatchEvent(new CustomEvent("vendor-guide:started"));setTour(name);setIndex(next);setLibrary(false);setWelcome(false);setMinimized(false);setReady(false);const destination=tutorialCatalog[name].steps.slice(0,next+1).findLast(item=>item.route)?.route;if(destination&&destination!==route)router.push(destination);}
 useEffect(()=>{const open=()=>{setLibrary(true);setWelcome(false);};const launch=(e:Event)=>start((e as CustomEvent<TutorialName>).detail);addEventListener("vendor-tour:open-library",open);addEventListener("vendor-tour:start",launch);return()=>{removeEventListener("vendor-tour:open-library",open);removeEventListener("vendor-tour:start",launch);};},[]); // Events start a fresh lesson; route is resolved by the step effect.
 useEffect(()=>{if(pathname!=="/dashboard/vendor")return;try{if(localStorage.getItem("linkwe-academy:v2-welcome"))return;}catch{return;}const timer=setTimeout(()=>{setWelcome(true);setLibrary(true);try{localStorage.setItem("linkwe-academy:v2-welcome","1");}catch{}},1200);return()=>clearTimeout(timer);},[pathname]);
 useEffect(()=>{if(!tour||!step)return;setReady(false);setSpot(null);if(step.route&&route!==step.route){router.push(step.route);return;}if(innerWidth<768)dispatchEvent(new CustomEvent(step.mobileMore?"vendor-tour:open-more":"vendor-tour:close-more"));let frame=0;let cancelled=false;
 const measure=()=>{if(cancelled)return;const modal=document.querySelector<HTMLDialogElement>("dialog[open]");setRoot(modal??document.body);const el=visible(step.selector);setFound(Boolean(el));if(!el||minimized){setSpot(null);return;}const r=el.getBoundingClientRect();const next={left:Math.max(6,r.left-5),top:Math.max(6,r.top-5),width:Math.max(0,Math.min(innerWidth-12,r.width+10)),height:Math.max(0,Math.min(innerHeight-12,r.height+10))};setSpot(current=>current&&Object.keys(next).every(key=>Math.abs(current[key as keyof typeof next]-next[key as keyof typeof next])<1)?current:next);};
 const schedule=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(measure);};const observer=new MutationObserver(schedule);observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["open","hidden","aria-expanded"]});addEventListener("scroll",schedule,true);addEventListener("resize",schedule);schedule();const timer=setTimeout(()=>{setReady(true);heading.current?.focus({preventScroll:true});},350);return()=>{cancelled=true;clearTimeout(timer);cancelAnimationFrame(frame);observer.disconnect();removeEventListener("scroll",schedule,true);removeEventListener("resize",schedule);};
 },[tour,index,step,route,router,minimized]);
 useEffect(()=>{if(!tour)return;const key=(e:KeyboardEvent)=>{if(e.key==="Escape"){e.preventDefault();close();}};addEventListener("keydown",key);return()=>removeEventListener("keydown",key);},[tour,close]);
 function move(next:number){if(!tour||!definition)return;const safe=Math.max(0,Math.min(next,definition.steps.length-1));saveTutorialProgress(tour,safe);setIndex(safe);setMinimized(false);}
 function show(){if(!step)return;const selector=step.activateSelector??step.navigateSelector;const target=visible(selector??step.selector);if(!target)return;if(selector){if(target instanceof HTMLAnchorElement || (target instanceof HTMLButtonElement&&target.type!=="submit"))target.click();if(step.navigateSelector)move(index+1);}else{target.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});target.focus({preventScroll:true});}}
 return <>{library&&<TutorialLibrary welcome={welcome} onClose={()=>{setLibrary(false);setWelcome(false);}} onStart={start}/>} {tour&&definition&&step&&root&&createPortal(<div className={s.layer}>{spot&&!minimized&&<div className={s.spot} style={spot}/>}<section className={`${s.coach} ${minimized?s.minimized:""}`} role="region" aria-label={`${definition.label} guided lesson`} data-placement={spot&&spot.top>innerHeight/2?"top":"bottom"}><header><span><img src="/images/home/rex-brand-v2.webp" alt=""/>YOUR LINKWE GUIDE</span><button onClick={()=>close()} aria-label="Pause and close lesson"><X size={18}/></button></header>{minimized?<button className={s.resume} onClick={()=>setMinimized(false)}>Continue: {step.title}<ArrowRight size={17}/></button>:<><div className={s.meta}><span>{definition.label}</span><span>{index+1} / {definition.steps.length}</span></div><progress max={definition.steps.length} value={index+1} aria-label="Lesson progress"/><div className={s.explanation} key={`${tour}-${index}`}><h2 ref={heading} tabIndex={-1}>{step.title}</h2><p>{step.body}</p>{step.note&&<aside>{step.note}</aside>}{ready&&step.selector&&!found&&<p className={s.missing}>This part isn’t visible yet. It may need a saved record, a plan upgrade or a choice on this page. You can continue the lesson or return later.</p>}{found&&<button className={s.show} onClick={show}><Eye size={16}/>{step.activateSelector||step.navigateSelector?"Open this control":"Show me where"}<ArrowRight size={14}/></button>}</div><footer><button disabled={index===0} onClick={()=>move(index-1)}><ArrowLeft size={16}/>Back</button>{index===definition.steps.length-1?<button className={s.next} onClick={()=>close(true)}>Finish lesson<Check size={16}/></button>:<button className={s.next} onClick={()=>move(index+1)}>Next step<ArrowRight size={16}/></button>}</footer><div className={s.bottom}><button onClick={()=>setMinimized(true)}><Pause size={12}/>Let me try</button><select aria-label="Jump to a lesson step" value={index} onChange={e=>move(Number(e.target.value))}>{definition.steps.map((item,i)=><option key={i} value={i}>{i+1}. {item.title}</option>)}</select></div><p className={s.saved}>Your place is saved. Press Esc to pause.</p></>}</section></div>,root)}</>;
}
